import {townChat} from './chapter-two-town.js';
import {addItem,countItem,removeItem} from './inventory.js';
export const C2_STAGES=['sleep','caravan','road_clear','road_return','city_letter','courier','inn_choice','inn_fight','cellar','tail','manor_search','manor_report','manor_order','manor_assault','boss_loot','captain_final','order_meeting','done'];
export const C2_OBJECTIVES={sleep:'Доставьте письмо Альфреда в королевство',caravan:'Поговорите с караванщиком у застрявшего обоза',road_clear:'Освободите заставу у моста от культистов',road_return:'Сообщите Брану, что дорога свободна',city_letter:'Доставьте письмо капитану Эдрику в Вальден',courier:'Найдите посыльного в трактире «Последний огонь»',inn_choice:'Расспросите трактирщика о пропавших людях',inn_fight:'Победите надзирателя и охрану трактира',cellar:'Спуститесь в погреб и освободите посыльного',tail:'Следуйте за тюремной повозкой, держась на расстоянии',manor_search:'Найдите пленного посыльного во владениях Северина',manor_report:'Вернитесь к капитану Эдрику с показаниями посыльного',manor_order:'Поговорите с капитаном о нападении на поместье',manor_assault:'Победите управляющего Северина',boss_loot:'Подберите перстень Северина',captain_final:'Покажите перстень Северина капитану Эдрику',order_meeting:'Поговорите с рыцарем Роландом в Вальдене',done:'Глава 2 завершена · вас ждут в крепости Ордена'};
export function chapterTwoQuest({p,slots,world,show,close,sync,sound,reward,shop,lootMenu=()=>{},voice=()=>{},bags=()=>[],stored=()=>[]}){
 let state={stage:'sleep',route:null,roadOpen:false,courierFreed:false,scouts:'idle',seals:'idle'};const active=()=>p.stage==='chapter_two';
 const owned=id=>countItem(slots,id)+countItem(stored(),id)+bags().reduce((sum,b)=>sum+b.items.filter(i=>i.id===id).reduce((n,i)=>n+i.count,0),0);
 function flags(){world?.setStory({...state,innHostile:['inn_fight','cellar'].includes(state.stage),followCart:state.stage==='tail',cellarOpen:state.stage==='cellar'||state.courierFreed,manorShortcut:['manor_assault','boss_loot','captain_final','order_meeting','done'].includes(state.stage),orderPresent:['order_meeting','done'].includes(state.stage)})}
 function advance(stage){state.stage=stage;flags();sync();sound()}
 function objective(){if(world?.raidActive)return 'Вальден под атакой\nПобедите последователей: '+world.mobs.filter(n=>n.group==='raid'&&n.hp>0).length+' осталось';return active()?'Дорога под защитой\n'+(state.stage==='tail'&&world.cartDone?'Повозка у ворот · подойдите к переходу и нажмите E':C2_OBJECTIVES[state.stage]):null}
 function optional(){const goals=[];if(state.scouts==='active')goals.push('Ночной дозор: победите разведчиков на тракте');if(state.scouts==='return')goals.push('Ночной дозор: вернитесь к сержанту Марте');if(state.seals==='active')goals.push('Знаки культа: принесите Грете 4 знака ('+countItem(slots,'cult_sign')+' / 4)');if(state.seals==='return')goals.push('Знаки культа: вернитесь к Грете');return goals.join('\n')}
 function tick(){if(!world)return;if(active()){if(state.stage==='road_clear'&&world.groupDefeated('road'))advance('road_return');if(state.stage==='inn_fight'&&world.groupDefeated('inn'))advance('cellar');if(state.stage==='manor_assault'&&world.boss?.hp===0)advance('boss_loot');if(state.stage==='boss_loot'&&countItem(slots,'vampire_signet'))advance('captain_final');if(['boss_loot','captain_final'].includes(state.stage)&&!owned('vampire_signet'))world.ensureSignet();if(state.scouts==='active'&&state.roadOpen)state.scouts='return';if(['active','return'].includes(state.seals))state.seals=countItem(slots,'cult_sign')>=4?'return':'active';flags();world.updateUI(marker)}}
 function marker(id){if(!active())return null;const s=state.stage;if(id==='c2-caravan')return {symbol:s==='caravan'?'!':s==='road_return'?'?':''};if(id==='c2-captain'&&['city_letter','manor_report','manor_order','captain_final'].includes(s))return {symbol:'?'};if(id==='c2-innkeeper'&&['courier','inn_choice'].includes(s))return {symbol:'?'};if(['c2-prisoner','c2-manor-courier'].includes(id)&&['cellar','manor_search'].includes(s))return {symbol:'?'};if(id==='c2-order'&&['order_meeting','done'].includes(s))return {symbol:s==='order_meeting'?'?':''};if(id==='c2-sergeant'&&state.scouts!=='done')return {symbol:state.scouts==='return'?'?':state.scouts==='idle'?'!':'',optional:true};if(id==='c2-city-smith'&&state.seals!=='done')return {symbol:state.seals==='return'?'?':state.seals==='idle'?'!':'',optional:true};return null}
 function talk(n){const s=state.stage;
 if(n.id==='c2-caravan'){if(s==='caravan'){show(n.name,'Ты из Темнолесья? Нас уже третий день держат перед мостом. На заставе люди в чёрном, требуют отдать им беженцев. Мы не согласились — они закрыли решётку. Если расчистишь путь, я проведу обоз до Вальдена. Заодно доставишь своё письмо.',[['Я освобожу мост',()=>{advance('road_clear');close()}],['Сначала подготовлюсь',close]]);return}if(s==='road_return'){state.roadOpen=true;advance('city_letter');reward(p,'c2-road','quest',350);sync();show(n.name,'Живы будем — не забудем. Капитана Эдрика найдёшь сразу за южными воротами Вальдена. Я отведу людей к городским очагам. А тем, кто зовёт в баронские владения, не верь на слово.');return}show(n.name,state.roadOpen?'Через мост прямо к Вальдену. Пусть там наконец услышат, что творится на дорогах.':'Сначала нужно убрать людей с заставы.');return}
 if(n.id==='c2-captain'){if(s==='city_letter'){if(!removeItem(slots,'alfred_letter')){show(n.name,'Мне нужно само письмо. Если оно осталось в сундуке или мешке — забери. Если потерял окончательно, попроси у Альфреда копию.');return}advance('courier');reward(p,'c2-letter','quest',300);sync();show(n.name,'Письмо Альфреда… Значит, и Темнолесье. Я уже отправлял к нему посыльного — Томаса. Он не вернулся. Людей у меня едва хватает на стены. Последний раз его видели в трактире «Последний огонь» за северными воротами. Найди его. Он умеет отличать разбойников от тех, кто только надевает их одежду.');return}if(s==='manor_report'||s==='manor_order'){advance('manor_order');show(n.name,'Томас рассказал про пленников. Значит, баронская «защита» — приманка. Мои люди помогут беженцам в городе, а тебе придётся добраться до управляющего. Северные ворота теперь выведут прямо к поместью. Светлые фонари в зале — старые обереги. Зажги хотя бы два: они ослабят кровавую защиту вампира.',[['Я займусь Северином',()=>{advance('manor_assault');close()}],['Мне нужны припасы',close]]);return}if(s==='captain_final'){if(!removeItem(slots,'vampire_signet'))return show(n.name,'Принеси перстень — его узнают люди барона.');reward(p,'c2-vampire','quest',850);advance('order_meeting');sync();show(n.name,'Это его печать. Пленники свободны, а дорога снова наша. Теперь ясно, зачем деревни доводили до отчаяния: люди сами шли к своим тюремщикам. Самого барона в поместье не было. Но к нам прибыл рыцарь Ордена — Роланд. Он искал следы этой переправки. Поговори с ним у северной площади.');return}show(n.name,s==='done'?'Вальден тебе обязан. Я отправил людей к мосту и велел сопровождать обозы.':'На стенах тихо — и это самое подозрительное. Найди Томаса, а затем разберёмся, кто здесь собирает людей.');return}
 if(n.id==='c2-innkeeper'){if(['courier','inn_choice'].includes(s)){advance('inn_choice');show(n.name,'Посыльный? Много кто здесь останавливается. Наш хозяин помогает людям перебраться в безопасное место. Еда, крыша, охрана — чего ещё желать? В погреб не ходи: там хозяйские запасы.',[['Освободить пленников силой',()=>{state.route='rescue';advance('inn_fight');show('Корвин','Надзиратель! У нас любопытный гость. Разберись с ним.')}],['Сделать вид, что поверил, и проследить за повозкой',()=>{state.route='tail';advance('tail');show('Под покровом ночи','Тюремная повозка у западной стены готовится к отъезду. Держись примерно в 8–45 метрах. Если отстанешь, возница задержится у дороги; если подойдёшь слишком близко, охрана заметит тебя.')}],['Сначала осмотреться',close]]);return}show(n.name,'Постоялый двор не место для расспросов. Иди своей дорогой.');return}
 if(['c2-prisoner','c2-manor-courier'].includes(n.id)){if(['cellar','manor_search'].includes(s)){state.courierFreed=true;reward(p,'c2-courier','quest',450);advance(state.route==='tail'?'manor_assault':'manor_report');show('Посыльный Томас','Я нёс ответ Альфреду. Увидел, как людей запирают в повозке, — и сам оказался за решёткой. Их увозят к управляющему Северину. Я видел, как он пил кровь возницы. Нападения на деревни должны заставить людей согласиться на его «защиту». Северин здесь не главный: он принимает приказы от барона. Я смастерил отмычку из пряжки. Как отвлечёшь охрану, сам открою замок и выведу пленников. '+(state.route==='tail'?'Управляющий в большом зале. Вон те светлые фонари — он велел их погасить.':'Возвращайся к капитану, пока они не спрятали следы.'));return}show(n.name,'Мы дождёмся помощи у дороги. Спасибо тебе.');return}
 if(n.id==='c2-order'){if(s==='order_meeting'){show(n.name,'Ты освободил пленников? Хорошая работа. Где ты учился так сражаться?.. Впрочем, сейчас не время. Мы преследуем тех, кто отправляет людей к вампирам. Барон держит несколько таких дворов. Прибудь в нашу крепость, когда будешь готов. Назовёшь моё имя.',[['Вы знакомы с бароном?',()=>show(n.name,'Знаем его слуг. Сам он редко показывается там, где можно встретить сопротивление. Северин управлял одной переправой. Другие ещё работают.',[['Продолжить',()=>talk(n)]])],['Почему ты так на меня смотришь?',()=>show(n.name,'Твой салют… так отдают честь у нас в школе. Может, перенял у кого-нибудь в дороге. Не забивай себе голову сейчас.',[['Продолжить',()=>talk(n)]])],['Я приду в крепость',()=>{advance('done');reward(p,'c2-order','quest',250);sync();show('Глава 2 завершена','Вы машинально отвечаете знакомым жестом, но не можете вспомнить, где его выучили. Роланд отводит взгляд.\n\nВальден получил передышку. Следующий путь ведёт в крепость Ордена — её история продолжится в третьей главе.')}]]);return}show(n.name,'У ворот крепости назови моё имя. И держись подальше от баронских повозок — если не собираешься вскрывать ещё одну.');return}
 if(n.id==='c2-city-smith'){const choices=[['Открыть кузницу',()=>shop('city_smith')]];if(state.seals==='idle')choices.unshift(['Есть работа?',()=>show(n.name,'Собери четыре знака с людей, которые перекрыли тракт. Надо знать, какая шайка стоит за железом на их доспехах.',[['Возьмусь',()=>{state.seals='active';sound();sync();close()}],['Позже',close]])]);if(state.seals==='return')choices.unshift(['Отдать четыре знака культа',()=>{if(removeItem(slots,'cult_sign',4)){state.seals='done';reward(p,'c2-seals','quest',220);sound();sync();show(n.name,'Это не случайные разбойники. Одинаковые крепления, одинаковые клейма. Кто-то снаряжает их целыми отрядами.')}}]);choices.push(['До встречи',close]);show(n.name,'Железо и дело. Оружие подберу по твоей руке, чужое навязывать не стану.',choices);return}
 if(n.id==='c2-city-innkeeper'){show(n.name,'Горячий эль, еда и место у очага. Беженцам сначала даём поесть, о плате спрашиваем потом.',[['Посмотреть припасы',()=>shop('city_cook')],['Кто прибыл с тракта?',()=>show(n.name,'Бран привёл людей из двух хуторов. У всех одна история: сперва звери, потом пропавшие, а затем добрые люди с повозкой. Уж слишком добрые.')],['До встречи',close]]);return}
 if(n.id==='c2-city-hunter'){show(n.name,'Ворота крепкие, а по ту сторону всё равно приходится ходить пешком. Рагу согреет, стрелы береги.',[['Открыть лавку',()=>shop('hunter')],['До встречи',close]]);return}
 if(['c2-herbalist','c2-alchemist','c2-leatherworker'].includes(n.id)){const merchant={'c2-herbalist':'city_herbalist','c2-alchemist':'city_alchemist','c2-leatherworker':'city_leather'}[n.id];show(n.name,n.id==='c2-leatherworker'?'Хорошую сумку шьют один раз. Чем прочнее кожа, тем больше в неё можно уложить. Улучшения постоянные, прежние ячейки сохранятся.':'Есть припасы для дороги. Лечить вслепую не стану: посмотри, что тебе нужно.',[['Посмотреть товары',()=>shop(merchant)],['Расскажи о городе',()=>townChat(n,show,close)],['До встречи',close]]);return}if(n.id==='c2-sergeant'){if(state.scouts==='idle'){show(n.name,'До меня только что дошёл приказ отправить дозор к мосту. Погоди… Это ты уже освободил заставу? А я всё собиралась просить о помощи. Возьми плату за работу — теперь мои люди смогут провести обозы.',[['Застава свободна, Бран подтвердит',()=>{state.scouts='active';sound();sync();close()}],['Не сейчас',close]]);return}if(state.scouts==='return'){state.scouts='done';reward(p,'c2-watch','quest',180);sound();sync();show(n.name,'Бран подтвердил: дорога свободна. Наш патруль займёт заставу. Вот твоя плата.');return}show(n.name,state.scouts==='done'?'Наш дозор уже занял заставу. Ты хорошо помог городу.':'Люди у моста ещё держатся. Разберись с ними.');return}townChat(n,show,close)}
 function interact(){if(!world)return false;const a=world.action();if(!a)return false;if(a.type==='enter'){if(!active()&&p.stage!=='kingdom_road'){show('Королевский тракт','Сначала получите письмо Альфреда после разговора со звонарём.');return true}if(!active()){p.stage='chapter_two';state.stage='caravan'}world.enter('road');flags();sync();sound();show('Глава 2. Дорога под защитой','За частоколом начинается старый королевский тракт. Впереди скрипят колёса и слышны голоса людей. К Вальдену вы идёте не один.');return true}if(a.type==='village'){world.resetCombat();world.leave();sync();return true}if(a.type==='travel'){if(a.to==='city'&&world.mode==='road'&&!state.roadOpen){show('Застава закрыта','Сначала освободите мост и поговорите с Браном.');return true}if(a.to==='inn'&&state.stage==='city_letter'){show('Северные ворота','Сначала передайте письмо капитану Эдрику. Он стоит у южных ворот.');return true}if(a.to==='manor'&&state.stage==='tail'&&world.cartDone)advance('manor_search');if(a.to==='manor'&&!['manor_search','manor_assault','boss_loot','captain_final','order_meeting','done'].includes(state.stage)){show('Дорога к поместью','Узнайте, куда увозят пленников.');return true}world.resetCombat();world.enter(a.to,a.back?{position:[a.to==='road'?2000:2400,1.7,a.to==='road'?-229:-215],yaw:Math.PI,pitch:0}:undefined);flags();sync();return true}if(a.type==='cellar'){if(state.stage!=='cellar'&&!state.courierFreed){show('Люк в погреб','Надзиратель держит ключ. Придётся разобраться с охраной.');return true}world.cellar();return true}if(a.type==='cellar_exit'){world.cellar(true);return true}if(world.raidActive&&!['travel','village'].includes(a.type)){show('Вальден под атакой','Сначала победите всех нападающих.');return true}if(a.type==='lantern'){world.lightLantern(a.index);sound();show('Освящённый свет','Свет мешает вампиру вытягивать жизнь. Два зажжённых фонаря также разрушат его кровавую защиту.');return true}if(a.type==='checkpoint'){p.checkpoint={id:'c2-'+world.mode,zone:'c2_'+world.mode,position:[a.fire.x+2.2,1.7,a.fire.z]};sound();show('Контрольная точка','После гибели и при использовании косточки возвращения вы вернётесь к этому очагу.');return true}if(a.type==='chest'){lootMenu(world.openChest(a.chest));sound();return true}if(world.raidActive&&!['travel','village'].includes(a.type)){show('Вальден под атакой','Сначала отбейте налёт последователей. Жители укрылись, лавки временно закрыты.');return true}if(a.type==='npc'){voice(a.npc.woman?'villager-woman':'villager-'+(1+Math.floor(Math.random()*3)));talk(a.npc);return true}return false}
 function alfred(){if(state.stage==='city_letter'&&!owned('alfred_letter')){if(!addItem(slots,'alfred_letter'))return show('Альфред','Освободи ячейку для копии письма.');show('Альфред','Держи копию. Я переписал письмо на случай, если посыльного снова перехватят. Теперь отнеси его капитану Эдрику.');return}show('Альфред','Наше дело теперь зависит и от Вальдена. Доведи начатое до конца, а деревня ещё продержится.')}
 function navigation(){if(!active())return null;if(world.raidActive){const n=world.mobs.find(n=>n.group==='raid'&&n.hp>0);if(n)return [n.g.position.x,n.g.position.z]}const s=state.stage,m=world.mode;if(!m)return [0,-118];let zone='city',pos=[2406,-39],id=null;if(['caravan','road_clear','road_return'].includes(s)){zone='road';id='c2-caravan';if(s==='road_clear'){const n=world.mobs.filter(n=>n.group==='road'&&n.hp>0).sort((a,b)=>a.g.position.distanceToSquared(world.citizens[0]?.g.position||a.g.position)-b.g.position.distanceToSquared(world.citizens[0]?.g.position||b.g.position))[0];pos=n?[n.g.position.x,n.g.position.z]:[2000,-118];id=null}}else if(['courier','inn_choice','inn_fight','cellar','tail'].includes(s)){zone='inn';id='c2-innkeeper';if(s==='tail'){id=null;const c=world.cartPosition;pos=c?[c[0],c[2]]:[2800,-181]}if(s==='inn_fight'){id=null;const n=world.mobs.find(n=>n.group==='inn'&&n.hp>0);pos=n?[n.g.position.x,n.g.position.z]:[2806,-139]}if(s==='cellar'){id=world.inCellar?'c2-prisoner':null;pos=[2806,-139]}}else if(['manor_search','manor_assault','boss_loot'].includes(s)){zone='manor';id=s==='manor_search'?'c2-manor-courier':null;pos=s==='manor_search'?[3242,-98]:[world.boss?.g.position.x||3200,world.boss?.g.position.z||-184]}else if(['order_meeting','done'].includes(s))id='c2-order';if(id){const n=world.citizens.find(n=>n.id===id);if(n)pos=[n.g.position.x,n.g.position.z]}if(m===zone)return pos;if(m==='road')return [2000,-234];if(m==='city')return zone==='road'?[2400,-20]:[2400,-224];if(m==='inn')return zone==='manor'?[2800,-181]:[2800,-18];return [3200,-18]}
 return {navigation,alfred,active,objective,optional,tick,interact,marker,snapshot:()=>({...state}),restore(s){state={stage:'sleep',route:null,roadOpen:false,courierFreed:false,scouts:'idle',seals:'idle',...s};flags()},get state(){return state}};
}
